from pathlib import Path
from PIL import Image
import base64, io, html, re

ROOT = Path(__file__).parent
REPO = ROOT.parent
def image_data(path, maxsize=1100, crop=None):
    im=Image.open(path).convert('RGBA')
    if crop: im=im.crop(crop)
    im.thumbnail((maxsize,maxsize))
    b=io.BytesIO(); im.save(b,format='WEBP',quality=88)
    return 'data:image/webp;base64,'+base64.b64encode(b.getvalue()).decode()
portrait=image_data(ROOT/'assets/portrait.png')
logo=image_data(ROOT/'assets/logo.png',900,(60,230,840,610))
ferris=image_data(ROOT/'assets/ferris.jpg')
fonts=''
for n,(family,weight) in enumerate([('Bricolage Grotesque',400),('Bricolage Grotesque',600),('Bricolage Grotesque',800),('DM Sans',400),('DM Sans',500)]):
    fonts+=f"@font-face{{font-family:'{family}';font-weight:{weight};src:url(data:font/ttf;base64,{base64.b64encode((ROOT/f'assets/font-{n}.ttf').read_bytes()).decode()}) format('truetype');font-display:swap;}}"
projects=[('Harley-Davidson','HD-logo-folio 2.webp','harley-davidson','Model Year 2024 Launch: "Ride Into a New Era"'),('City of Chicago','chi-logo-folio-1.webp','city-of-chicago','City of Chicago: "One Home Team"'),('Recent Web Projects','Capture.webp','recent-web-projects','Websites, content strategy & digital experience'),('Cox Communications','cox-logo-folio-1.webp','cox-mobile',''),('Converse','converseLogo.webp','converse',''),('Thunder Valley','TVCR cover photo logo.webp','thunder-valley','')]
tiles=''
for name,asset,route,desc in projects:
    tiles+=f'<a class="project" href="https://www.anastasiaguletsky.com/{route}" target="_blank" rel="noopener"><img src="{image_data(REPO/"public/assets"/asset,850)}" alt="{name} campaign" loading="lazy"><div><h3>{name} <span aria-hidden="true">↗</span></h3><p>{html.escape(desc)}</p></div></a>'
bio="👋 I'm Anastasia, an award-winning creative and copy leader with 14 years of experience shaping brand voice, leading multi-channel campaigns, building digital content strategies and growing teams who don't get the Sunday Scaries."
bookintro='I write picture books and introduce kids to the people and places that should absolutely have their own HBO show by now—overlooked historical figures, Chicago stories that are bigger than Chicago, women who were doing it all and then some. You know the type: she did the work, he got the Wikipedia page.'
bookmore='Honestly? Kids have enough books about the guys in wigs we had to memorize for history class (wish I were referring to drag queens, but alas). I’m going deeper into the archives, into the hidden gems, into the stories that actually stick with people because they’ve never heard them before. As a member of SCBWI, I’m building a list of books that should have existed a long time ago.'
contactcopy="Looking for a creative lead, copy freelancer, author talk or a new friend who isn't afraid of karaoke duets? Then let's talk business and song lists."
bookdesc='The 1893 origin story of the iconic dessert, and the even more iconic Chicago woman behind its creation: Bertha Palmer.'
def paths():
    return '<div class="paths"><a class="path creative-path" href="#creative"><span class="eyebrow">Brand storytelling</span><strong>Creative work <span>↗</span></strong><small>Found Fable Creative Co. · Portfolio</small></a><a class="path book-path" href="#books"><span class="eyebrow">Children’s books</span><strong>Books <span>↗</span></strong><small>Bertha · Oct 3, 2027</small></a></div>'
def photo(): return f'<figure class="portrait"><img src="{portrait}" alt="Anastasia Guletsky Kelly smiling in front of a butterfly mural"><figcaption>Anastasia Guletsky Kelly</figcaption></figure>'
def bookfeature(): return f'<div class="book-feature"><figure><img src="{ferris}" alt="Archival Ferris wheel photograph used on the current books page"><figcaption>Archival image · cover artwork forthcoming</figcaption></figure><div class="book-copy"><span class="eyebrow">Coming October 3, 2027</span><h2>BERTHA &amp; THE VERY FIRST BROWNIE</h2><p>{bookdesc}</p><p>Published by <a href="https://bushelandpeckbooks.com/" target="_blank" rel="noopener">Bushel &amp; Peck Books ↗</a></p><a class="button teal" href="#contact-books">Books, schools, libraries &amp; events ↗</a></div></div>'

