JS='''
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();document.querySelector('main').focus();});
const nav=document.querySelector('.nav'), menu=document.querySelector('.menu');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);menu.textContent=open?'Close':'Menu';});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='Menu';}});
function selectTopic(topic){document.querySelectorAll('[data-topic]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.topic===topic)));document.querySelector('#topic').value=topic;}
document.querySelectorAll('[data-topic]').forEach(b=>b.addEventListener('click',()=>selectTopic(b.dataset.topic)));
function route(){let key=location.hash.slice(1)||'home';if(key.startsWith('contact')){selectTopic(key==='contact-books'?'Books, schools, libraries & events':'Brand & creative work');key='contact';}if(!['home','creative','books','contact'].includes(key))key='home';document.querySelectorAll('main > section').forEach(s=>s.hidden=s.id!==key);document.querySelectorAll('.nav a').forEach(a=>{if(a.hash==='#'+key)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='Menu';document.title='Anastasia Guletsky Kelly — '+({home:'Home',creative:'Creative work',books:'Books',contact:'Contact'}[key]);window.scrollTo(0,0);}
window.addEventListener('hashchange',()=>{route();document.querySelector('main').focus({preventScroll:true});});route();
document.querySelector('form').addEventListener('submit',e=>{e.preventDefault();document.querySelector('.form-message').hidden=false;document.querySelector('.form-message').focus();});
'''

for n,cls,title in [(1,'one','The Editorial Introduction'),(2,'two','Two Open Doors'),(3,'three','The Storyteller')]:
    if n==1:
        home=f'<div class="hero"><div class="hero-grid"><div><span class="eyebrow">Anastasia Guletsky Kelly</span><h1>Creative director.<br>Author.<br>Friend<span style="display:inline;color:var(--coral)">.</span></h1><p class="roles">Creative Director // Author // Friend</p><p class="bridge">Brand storytelling. Children’s books.</p></div>{photo()}</div>{paths()}</div>'
    elif n==2:
        home=f'<div class="hero"><div class="hero-top"><div><p class="roles">Creative Director // Author // Friend</p><h1>Anastasia<br>Guletsky Kelly<span style="color:var(--coral)">.</span></h1></div>{photo()}</div>{paths()}</div>'
    else:
        home=f'<div class="hero"><h1 class="masthead">Anastasia<br>Guletsky Kelly<span style="color:var(--coral)">.</span></h1><div class="hero-grid">{photo()}<div><p class="roles">Creative Director // Author // Friend</p><h2>Brand storytelling.<br>Children’s books.</h2>{paths()}</div></div></div>'
    home+=f'<div class="intro-band"><div><span class="eyebrow">Creative Director &amp; Founder</span><h2>Found Fable<br>Creative Co.</h2></div><div><p>{bio}</p><a class="quiet" href="https://foundfablecreative.com/" target="_blank" rel="noopener">Found Fable Creative Co. ↗</a></div></div>'
    creative=f'<div class="page-head"><span class="eyebrow">Brand storytelling</span><h1>Creative work<span style="color:var(--coral)">.</span></h1><p class="lead">{bio}</p></div><p><a class="button" href="#contact-creative">Brand &amp; creative work ↗</a></p><div class="section-top"><h2>Portfolio</h2><a class="quiet" href="https://www.anastasiaguletsky.com/resume" target="_blank" rel="noopener">My resume ↗</a></div><div class="projects">{tiles}</div><div class="freelance"><div><span class="eyebrow">Creative Director &amp; Founder</span><h2>Found Fable<br>Creative Co.</h2></div><div><p>Launched a creative consultancy specializing in brand voice development, content strategy and storytelling for mission-driven organizations.</p><a class="button" href="#contact-creative">Brand &amp; creative work ↗</a><p><a class="quiet" href="https://foundfablecreative.com/" target="_blank" rel="noopener">Found Fable Creative Co. ↗</a></p></div></div><div class="clients"><span class="eyebrow">Clients</span><h2>some of my many voices:</h2><div class="client-names"><span>Harley-Davidson</span><span>City of Chicago</span><span>Cox</span><span>Converse</span><span>Michaels</span><span>Thunder Valley</span></div></div><div class="writing"><span class="pending">Content slot · for review</span><h3>Freelance articles</h3><p>Article titles, publication names and links to be supplied.</p></div>'
    books=f'<div class="page-head"><span class="eyebrow">Children’s books</span><h1>Same storyteller.<br>New client: kids.</h1></div><div class="author-copy"><h2>Creative Director<br> // Author<br> // Friend</h2><div><p>{bookintro}</p><p>{bookmore}</p></div></div>{bookfeature()}<div class="more-books"><h2>And there\'s more to come!</h2><ul><li>The first Greek woman to immigrate to Chicago in 1885.</li><li>The silly little weiner dog who inspired the Portillo\'s Hot Dog empire.</li><li>An art museum + dealing with big feelings + two lions.</li></ul><p>Stay tuned!</p><a class="button teal" href="#contact-books">Books, schools, libraries &amp; events ↗</a></div>'
    contact=f'<div class="page-head"><span class="eyebrow">Contact</span><h1>let’s chat!</h1></div><div class="contact-layout"><div><p class="lead">{contactcopy}</p>{photo()}</div><div><div class="contact-choices" role="group" aria-label="Inquiry type"><button class="choice" data-topic="Brand & creative work" aria-pressed="true">Brand &amp; creative work ↗</button><button class="choice" data-topic="Books, schools, libraries & events" aria-pressed="false">Books, schools, libraries &amp; events ↗</button></div><form><input type="hidden" id="topic" name="topic" value="Brand & creative work"><label for="name">Name</label><input id="name" name="name" autocomplete="name" required><label for="email">Email</label><input id="email" name="email" type="email" autocomplete="email" required><label for="message">Message</label><textarea id="message" name="message" required></textarea><p class="form-note">Interactive mockup — this form does not send messages.</p><button class="button" type="submit">Preview inquiry →</button><p class="form-message" role="status" tabindex="-1" hidden>Your inquiry preview is complete. Nothing has been sent. Use the <a href="https://www.anastasiaguletsky.com/contact" target="_blank" rel="noopener">current contact page ↗</a> to get in touch.</p></form></div></div>'
    doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="AGK design concept {n}: {title}. Interactive review mockup."><title>AGK — {title}</title><style>{fonts}{CSS}</style></head><body class="{cls}"><a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="wrap header-inner"><a class="logo" href="#home" aria-label="AGK home"><img src="{logo}" alt="AGK"></a><button class="menu" aria-expanded="false" aria-controls="navigation">Menu</button><nav id="navigation" class="nav" aria-label="Main navigation"><a href="#home">Home</a><a href="#creative">Creative work</a><a href="#books">Books</a><a href="#contact">Contact</a></nav></div></header><main id="main" tabindex="-1" class="wrap"><section id="home">{home}</section><section id="creative" hidden>{creative}</section><section id="books" hidden>{books}</section><section id="contact" hidden>{contact}</section></main><footer class="site-footer"><div class="wrap"><div class="footer-top"><div class="footer-name">Anastasia<br>Guletsky Kelly</div><div class="footer-links"><a href="#creative">Creative work</a><a href="#books">Books</a><a href="#contact">Contact</a><a href="https://foundfablecreative.com/" target="_blank" rel="noopener">Found Fable ↗</a><a href="https://www.linkedin.com/in/anastasiaguletsky" target="_blank" rel="noopener">LinkedIn ↗</a><a href="https://www.facebook.com/stasiamarie" target="_blank" rel="noopener">Facebook ↗</a></div></div><div class="footer-bottom"><span>Creative Director // Author // Friend</span><span>Design study 0{n} · {title}</span></div></div></footer><script>{JS}</script></body></html>'''
    (ROOT/f'0{n}-{cls}.html').write_text(doc,encoding='utf-8')
print('Built 3 self-contained HTML concepts.')
